'use strict';
// Maps the old test paths and block ids onto gothik's engine files (src/go/core) and data (src/go/data; the
// lessons and tracks are the Academy's Go courses, built into src/academy/generated by scripts/build-academy.mjs).
// Tests still ask for src/go-interpreter.js, src/models/*.js, src/engine/*.js and src/content/*.json relative to
// tests/ (run as classic vm scripts or read with fs), so fs.readFileSync serves those virtual paths and nothing else.
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.join(__dirname, '..'); // the old tests' paths (relative ones too: they ran from the package root) resolve from here
const REPO = path.join(__dirname, '..', '..');
const read = (rel) => realRead.call(fs, path.join(REPO, rel), 'utf8');
const realRead = fs.readFileSync;
// ES `export` lines only sit at the end of core files; classic vm scripts cannot contain them.
const stripExports = (text) => text.replace(/^export .*$/gm, '');

const CODE = {
  engine: 'src/go/core/engine.js',
  stage: 'src/go/core/stage.js',
  'editor-script': 'src/go/core/editor.js',
  modules: 'src/go/core/labs.js',
};
const DATA = {
  'program-library': 'program-library.json',
  'path-data': 'path.json',
  'glossary-data': 'glossary.json',
  'feature-registry': 'feature-registry.json',
  'gotcha-data': 'gotcha.json',
  'interview-data': 'interview.json',
  'compare-data': 'compare.json',
  'i18n-data': 'i18n.json',
  'corpus-index': 'corpus-index.json',
  catalog: 'catalog.json',
  'build-meta': 'build-meta.json',
  'academy-reading': 'academy-reading.json',
  'trace-sample': 'trace-sample.txt',
};
// Old virtual JSON paths and the data id each one stands for.
const VIRTUAL_JSON = {
  'src/content/lessons.json': 'curriculum',
  'src/content/programs.json': 'program-library',
  'src/content/glossary.json': 'glossary-data',
  'src/content/paths.json': 'path-data',
  'src/content/tracks.json': 'track-data',
  'src/engine/features.json': 'feature-registry',
};
// Old virtual code paths: every one is served by the same engine file.
const VIRTUAL_CODE = /^src\/(go-interpreter\.js|models\/[\w-]+\.js|engine\/[\w-]+\.js)$/;

function block(id) {
  if (CODE[id]) return stripExports(read(CODE[id]));
  if (id === 'curriculum') return read('src/academy/generated/go-curriculum.json');
  if (id === 'track-data') return JSON.stringify(JSON.parse(read('src/academy/generated/index.json')).courses.filter((c) => c.engine === 'go').map((c) => ({ id: c.track, title: c.title })));
  if (DATA[id]) return read('src/go/data/' + DATA[id]);
  throw Error('no src/core or src/data file for block "' + id + '"');
}
const data = (id) => JSON.parse(block(id));
// Guarded so it runs once per vm context, like the old single script block.
const engine = () => 'if(!globalThis.__gothikEngine){globalThis.__gothikEngine=true;\n' + block('engine') + '\n}';

fs.readFileSync = function (file, options) {
  const rel = typeof file === 'string' ? path.relative(ROOT, path.resolve(ROOT, file)).split(path.sep).join('/') : '';
  let text = null;
  if (VIRTUAL_CODE.test(rel)) text = engine();
  else if (VIRTUAL_JSON[rel]) text = block(VIRTUAL_JSON[rel]);
  // the old tests/… paths (relative to the package root) are this folder now
  if (text === null) return realRead.call(this, typeof file === 'string' && /^tests\//.test(file) ? path.join(__dirname, file.slice(6)) : file, options);
  return options ? text : Buffer.from(text);
};

const realExists = fs.existsSync;
fs.existsSync = (file) => realExists.call(fs, typeof file === 'string' && /^tests\//.test(file) ? path.join(__dirname, file.slice(6)) : file);

module.exports = { block, data, engine };
